-- Run ONLY on an isolated test branch. All dedicated fixtures roll back.
DO $$
DECLARE
  actor_a uuid; actor_b uuid; origin uuid; destination uuid;
  product uuid; color uuid; receipt uuid; foreign_receipt uuid; order_id uuid;
  carton uuid; line_id uuid; document_id uuid; label_order uuid;
  movement uuid; reception uuid; legacy_box uuid; legacy_line uuid;
  transfer_movement uuid; transfer_id uuid; transfer_line uuid;
  before_count integer; actual integer; data jsonb;
BEGIN
  SELECT id INTO origin FROM branches WHERE name='Treviño';
  SELECT id INTO destination FROM branches WHERE name='Plaza del Audio';
  IF origin IS NULL OR destination IS NULL THEN RAISE EXCEPTION 'Missing controlled branches'; END IF;
  BEGIN
    INSERT INTO users(name,email,role) VALUES('AUDIT FIXTURE A',gen_random_uuid()||'@fixture.invalid','MASTER') RETURNING id INTO actor_a;
    INSERT INTO users(name,email,role) VALUES('AUDIT FIXTURE B',gen_random_uuid()||'@fixture.invalid','OPERATIVE') RETURNING id INTO actor_b;
    IF NOT EXISTS(SELECT 1 FROM audit_events WHERE user_id=actor_a AND entity_id=actor_a AND action='ROW_INSERT') THEN RAISE EXCEPTION 'Self sign-up attribution failed'; END IF;
    PERFORM set_config('app.audit_user_id',actor_a::text,true);
    INSERT INTO products(name) VALUES('AUDIT FIXTURE '||gen_random_uuid()) RETURNING id INTO product;
    UPDATE products SET name='AUDIT CHANGED '||product WHERE id=product;
    SELECT previous_value INTO data FROM audit_events WHERE entity_id=product AND action='ROW_UPDATE';
    IF data->>'name' NOT LIKE 'AUDIT FIXTURE %' THEN RAISE EXCEPTION 'Missing old value'; END IF;
    IF NOT EXISTS(SELECT 1 FROM audit_events WHERE entity_id=product AND user_id=actor_a AND new_value->>'name'='AUDIT CHANGED '||product) THEN RAISE EXCEPTION 'Missing new value'; END IF;
    SELECT count(*) INTO before_count FROM audit_events WHERE entity_id=product;
    UPDATE products SET name=name,updated_at=now() WHERE id=product;
    SELECT count(*) INTO actual FROM audit_events WHERE entity_id=product;
    IF actual<>before_count THEN RAISE EXCEPTION 'No-op was audited'; END IF;
    INSERT INTO product_colors(product_id,name) VALUES(product,'NEGRO') RETURNING id INTO color;
    DELETE FROM product_colors WHERE id=color;
    IF NOT EXISTS(SELECT 1 FROM audit_events WHERE entity_id=color AND action='ROW_DELETE' AND previous_value->>'name'='NEGRO' AND new_value IS NULL) THEN RAISE EXCEPTION 'Missing deleted value'; END IF;
    INSERT INTO user_login_credentials(user_id,password_hash) VALUES(actor_b,'FIXTURE_NOT_A_REAL_HASH');
    IF EXISTS(SELECT 1 FROM audit_events WHERE entity_id=actor_b AND (previous_value::text LIKE '%FIXTURE_NOT_A_REAL_HASH%' OR new_value::text LIKE '%FIXTURE_NOT_A_REAL_HASH%')) THEN RAISE EXCEPTION 'Credential leakage'; END IF;
    INSERT INTO user_module_permissions(user_id,module) VALUES(actor_b,'REGISTRO_SISTEMA');
    DELETE FROM user_module_permissions WHERE user_id=actor_b AND module='REGISTRO_SISTEMA';
    IF NOT EXISTS(SELECT 1 FROM audit_events WHERE entity_id=actor_b AND entity_type='user_module_permissions' AND action='ROW_DELETE') THEN RAISE EXCEPTION 'Permission revocation not audited'; END IF;
    INSERT INTO receiving_sessions(branch_id,reference,arrival_date,total_boxes,created_by) VALUES(origin,'AUDIT FIXTURE OWN',current_date,1,actor_a) RETURNING id INTO receipt;
    INSERT INTO receiving_orders(branch_id,reference,product_id,shipping,marking,destination_branch_id,created_by) VALUES(origin,'AUDIT FIXTURE OWN '||receipt,product,'SEA','PER',origin,actor_a) RETURNING id INTO order_id;
    INSERT INTO receiving_cartons(order_id,carton_number,session_id) VALUES(order_id,'1',receipt) RETURNING id INTO carton;
    INSERT INTO receiving_items(carton_id,model,color,expected) VALUES(carton,'A06','NEGRO',10) RETURNING id INTO line_id;
    PERFORM set_config('app.audit_user_id',actor_b::text,true);
    UPDATE receiving_items SET counted=0 WHERE id=line_id;
    IF NOT EXISTS(SELECT 1 FROM audit_events WHERE entity_id=line_id AND user_id=actor_b AND branch_id=origin AND action='ROW_UPDATE' AND previous_value->'counted'='null'::jsonb AND new_value->'counted'='0'::jsonb) THEN RAISE EXCEPTION 'Zero/null, actor or origin branch attribution failed'; END IF;
    PERFORM set_config('app.audit_user_id',actor_a::text,true);
    INSERT INTO receiving_documents(order_id,filename,mime,data,created_by) VALUES(order_id,'fixture.xlsx','application/octet-stream',decode('01020304','hex'),actor_a) RETURNING id INTO document_id;
    IF EXISTS(SELECT 1 FROM audit_events WHERE entity_id=document_id AND (new_value ? 'data' OR previous_value ? 'data')) THEN RAISE EXCEPTION 'Binary document leakage'; END IF;
    IF NOT EXISTS(SELECT 1 FROM audit_events WHERE entity_id=document_id AND new_value->>'filename'='fixture.xlsx') THEN RAISE EXCEPTION 'Document metadata missing'; END IF;
    SELECT count(*) INTO before_count FROM audit_events WHERE entity_id=document_id;
    UPDATE receiving_documents SET data=decode('05060708','hex') WHERE id=document_id;
    SELECT count(*) INTO actual FROM audit_events WHERE entity_id=document_id;
    IF actual<>before_count+1 THEN RAISE EXCEPTION 'Same-name binary replacement not audited'; END IF;
    INSERT INTO tiktok_label_orders(name,items) VALUES('AUDIT FIXTURE LABELS','[{"model":"A06","quantity":1}]') RETURNING id INTO label_order;
    UPDATE tiktok_label_orders SET printed_item_ids='["fixture"]' WHERE id=label_order;
    DELETE FROM tiktok_label_orders WHERE id=label_order;
    IF NOT EXISTS(SELECT 1 FROM audit_events WHERE entity_id=label_order AND action='ROW_DELETE' AND previous_value->>'name'='AUDIT FIXTURE LABELS') THEN RAISE EXCEPTION 'Label deletion not audited'; END IF;
    INSERT INTO inventory_movements(folio,movement_type,branch_id,created_by) VALUES('AUDIT FIXTURE LEGACY '||gen_random_uuid(),'RECEPTION',origin,actor_a) RETURNING id INTO movement;
    INSERT INTO receptions(movement_id,expected_boxes,product_id) VALUES(movement,1,product) RETURNING id INTO reception;
    INSERT INTO reception_boxes(reception_id,box_number) VALUES(reception,1) RETURNING id INTO legacy_box;
    INSERT INTO reception_box_lines(box_id,product_id,quantity) VALUES(legacy_box,product,1) RETURNING id INTO legacy_line;
    UPDATE reception_box_lines SET quantity=2 WHERE id=legacy_line;
    IF NOT EXISTS(SELECT 1 FROM audit_events WHERE entity_id=legacy_line AND movement_id=movement AND branch_id=origin AND action='ROW_UPDATE') THEN RAISE EXCEPTION 'Legacy movement attribution failed'; END IF;
    INSERT INTO inventory_movements(folio,movement_type,branch_id,created_by) VALUES('AUDIT FIXTURE TRANSFER '||gen_random_uuid(),'TRANSFER',origin,actor_a) RETURNING id INTO transfer_movement;
    INSERT INTO transfers(movement_id,origin_branch_id,destination_branch_id) VALUES(transfer_movement,origin,destination) RETURNING id INTO transfer_id;
    INSERT INTO transfer_lines(transfer_id,product_id,sent_quantity) VALUES(transfer_id,product,2) RETURNING id INTO transfer_line;
    PERFORM set_config('app.audit_user_id',actor_b::text,true);
    UPDATE transfer_lines SET received_quantity=2 WHERE id=transfer_line;
    IF NOT EXISTS(SELECT 1 FROM audit_events WHERE entity_id=transfer_line AND movement_id=transfer_movement AND branch_id=destination AND user_id=actor_b AND action='ROW_UPDATE') THEN RAISE EXCEPTION 'Transfer destination attribution failed'; END IF;
    INSERT INTO receiving_sessions(branch_id,reference,arrival_date,total_boxes,created_by) VALUES(origin,'AUDIT FIXTURE DESTINATION',current_date,1,actor_a) RETURNING id INTO foreign_receipt;
    INSERT INTO receiving_orders(branch_id,reference,product_id,shipping,marking,is_foreign,destination_branch_id,created_by) VALUES(origin,'AUDIT FIXTURE JAPS '||foreign_receipt,product,'AIR','JAPS',true,destination,actor_a) RETURNING id INTO order_id;
    INSERT INTO receiving_cartons(order_id,carton_number,session_id) VALUES(order_id,'1',foreign_receipt) RETURNING id INTO carton;
    INSERT INTO receiving_destination_arrivals(carton_id,order_id,branch_id,origin_session_id,origin_branch_id,received_by) VALUES(carton,order_id,destination,foreign_receipt,origin,actor_b);
    INSERT INTO receiving_items(carton_id,model,color) VALUES(carton,'A06','AZUL') RETURNING id INTO line_id;
    IF NOT EXISTS(SELECT 1 FROM audit_events WHERE entity_id=line_id AND branch_id=destination AND user_id=actor_b) THEN RAISE EXCEPTION 'Receiving destination attribution failed'; END IF;
    IF EXISTS(SELECT 1 FROM audit_fixture_pending WHERE id=order_id::text AND kind='DESTINATION') THEN RAISE EXCEPTION 'Uncounted destination appeared ready'; END IF;
    UPDATE receiving_cartons SET counted_at=now(),counted_by=actor_b WHERE id=carton;
    IF NOT EXISTS(SELECT 1 FROM audit_fixture_pending WHERE id=order_id::text AND kind='DESTINATION' AND branch_id=destination::text) THEN RAISE EXCEPTION 'Counted destination not pending'; END IF;
    INSERT INTO receiving_destination_registrations(carton_id,order_id,branch_id,counted_at,registered_by) SELECT b.id,b.order_id,destination,b.counted_at,actor_b FROM receiving_cartons b WHERE b.id=carton;
    IF EXISTS(SELECT 1 FROM audit_fixture_pending WHERE id=order_id::text AND kind='DESTINATION') THEN RAISE EXCEPTION 'Registered destination still pending'; END IF;
    IF NOT EXISTS(SELECT 1 FROM audit_events WHERE entity_type='receiving_destination_registrations' AND entity_id=carton AND branch_id=destination AND user_id=actor_b) THEN RAISE EXCEPTION 'Destination registration not audited'; END IF;
    UPDATE receiving_cartons SET counted_at=now()+interval '1 second' WHERE id=carton;
    IF NOT EXISTS(SELECT 1 FROM audit_fixture_pending WHERE id=order_id::text AND kind='DESTINATION' AND correction) THEN RAISE EXCEPTION 'Recount not queued as correction'; END IF;
    PERFORM set_config('app.audit_user_id','',true);
    SELECT count(*) INTO before_count FROM audit_events WHERE entity_id=product;
    UPDATE products SET name='NO ACTOR '||product WHERE id=product;
    SELECT count(*) INTO actual FROM audit_events WHERE entity_id=product;
    IF actual<>before_count THEN RAISE EXCEPTION 'Invented actor for old deployment'; END IF;
    RAISE EXCEPTION USING ERRCODE='Z0001',MESSAGE='fixture rollback';
  EXCEPTION WHEN SQLSTATE 'Z0001' THEN NULL;
  END;
END;
$$;
